/**
 * TrueType payloads for the PDF exports.
 *
 * jsPDF ships only the PDF base-14 faces (Helvetica, Times, Courier). Drawing a
 * quote with Helvetica while the on-screen preview uses Manrope/Newsreader made
 * the two documents disagree twice over: the wrong typeface, and — because every
 * column position and wrap point is measured with getTextWidth — different
 * alignment and line breaks. Embedding the real faces fixes both at once.
 *
 * This module is imported dynamically by the generators, so ~400KB of base64
 * lands in its own chunk and is fetched only when someone exports a PDF.
 */

export const MANROPE_REGULAR = "";

export const MANROPE_BOLD = "";

export const NEWSREADER_MEDIUM = "";
